-- =====================================================================
-- RMM IMSS - Script completo del catálogo de unidades y áreas
--
-- Qué hace:
--   1. Crea y llena las 9 tablas del catálogo institucional (base "estructura",
--      sin empleado ni acta).
--   2. Cambia Equipo.UnidadID por Equipo.AreaID y elimina la tabla Unidad.
--   3. Crea la vista v_estructura.
--   4. Muestra el conteo de registros para verificar.
--
-- Cómo ejecutarlo en MySQL Workbench:
--   - Selecciona la base del RMM (doble clic en ella en el panel SCHEMAS,
--     queda en negritas) o descomenta la línea USE de abajo con su nombre.
--   - Ejecuta todo con el rayo (Ctrl+Shift+Enter).
--   - Se puede volver a ejecutar: recarga el catálogo y no repite los cambios
--     a Equipo. OJO: al recargar, los IDs de area se conservan, así que los
--     equipos siguen apuntando a la misma área.
-- =====================================================================

-- USE `nombre_de_tu_base`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- =====================================================================
-- 1. Catálogo
-- =====================================================================

-- ---------------------------------------------------------------------
-- region
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `region`;
CREATE TABLE `region` (
  `id_region` tinyint unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id_region`),
  UNIQUE KEY `uq_region` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `region` VALUES (1,'REGION I HUAJUAPAN DE LEON     MIXTECA-CAÑADA'),(2,'REGION II  TLAXIACO   MIXTECA ALTA'),(5,'REGION III MIAHUATLAN DE PORFIRIO DIAZ       SIERRA SUR- COSTA'),(3,'REGION IV TLACOLULA     VALLES CENTRALES'),(4,'REGION V MATIAS ROMERO    ISTMO-PAPLIOAPAN');

-- ---------------------------------------------------------------------
-- zona
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `zona`;
CREATE TABLE `zona` (
  `num_zona` smallint unsigned NOT NULL,
  `id_region` tinyint unsigned NOT NULL,
  PRIMARY KEY (`num_zona`),
  KEY `fk_zona_region` (`id_region`),
  CONSTRAINT `fk_zona_region` FOREIGN KEY (`id_region`) REFERENCES `region` (`id_region`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `zona` VALUES (1,1),(2,1),(3,1),(4,1),(5,1),(6,1),(7,2),(8,2),(9,2),(10,2),(11,2),(12,2),(13,2),(20,3),(21,3),(22,3),(23,3),(24,3),(25,3),(26,4),(27,4),(28,4),(29,4),(30,4),(31,4),(32,4),(14,5),(15,5),(16,5),(17,5),(18,5),(19,5);

-- ---------------------------------------------------------------------
-- clasificacion_unidad
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `clasificacion_unidad`;
CREATE TABLE `clasificacion_unidad` (
  `id_clasificacion` smallint unsigned NOT NULL AUTO_INCREMENT,
  `tipo_unidad` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub_tipo_unidad` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `agrupacion_tipo` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id_clasificacion`),
  UNIQUE KEY `uq_clasificacion` (`tipo_unidad`,`sub_tipo_unidad`,`agrupacion_tipo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

