-- ---------------------------------------------------------------------
-- unidad_homologada
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `unidad_homologada`;
CREATE TABLE `unidad_homologada` (
  `id_unidad_homologada` smallint unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_clasificacion` smallint unsigned NOT NULL,
  `id_region` tinyint unsigned DEFAULT NULL,
  `num_zona` smallint unsigned DEFAULT NULL,
  PRIMARY KEY (`id_unidad_homologada`),
  UNIQUE KEY `uq_unidad_homologada` (`nombre`),
  KEY `fk_uh_clasif` (`id_clasificacion`),
  KEY `fk_uh_region` (`id_region`),
  KEY `fk_uh_zona` (`num_zona`),
  CONSTRAINT `fk_uh_clasif` FOREIGN KEY (`id_clasificacion`) REFERENCES `clasificacion_unidad` (`id_clasificacion`),
  CONSTRAINT `fk_uh_region` FOREIGN KEY (`id_region`) REFERENCES `region` (`id_region`),
  CONSTRAINT `fk_uh_zona` FOREIGN KEY (`num_zona`) REFERENCES `zona` (`num_zona`),
  CONSTRAINT `ck_uh_region_o_zona` CHECK (((`id_region` is null) or (`num_zona` is null)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

