-- ---------------------------------------------------------------------
-- unidad_cc
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `unidad_cc`;
CREATE TABLE `unidad_cc` (
  `id_unidad_cc` int unsigned NOT NULL AUTO_INCREMENT,
  `clave_ui` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `clave_cc` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_iman_desglosado` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uicc` varchar(20) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (concat(`clave_ui`,`clave_cc`)) STORED,
  PRIMARY KEY (`id_unidad_cc`),
  UNIQUE KEY `uq_unidad_cc` (`clave_ui`,`clave_cc`),
  UNIQUE KEY `uq_uicc` (`uicc`),
  KEY `fk_ucc_cc` (`clave_cc`),
  CONSTRAINT `fk_ucc_cc` FOREIGN KEY (`clave_cc`) REFERENCES `centro_costo` (`clave_cc`),
  CONSTRAINT `fk_ucc_ui` FOREIGN KEY (`clave_ui`) REFERENCES `unidad_informacion` (`clave_ui`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

