-- ---------------------------------------------------------------------
-- area
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `area`;
CREATE TABLE `area` (
  `id_area` int unsigned NOT NULL AUTO_INCREMENT,
  `id_unidad_cc` int unsigned NOT NULL,
  `division` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `subdivision` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `codigo_ubicacion` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_unidad_homologada` smallint unsigned DEFAULT NULL,
  `cuenta` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id_area`),
  UNIQUE KEY `uq_area` (`id_unidad_cc`,`division`,`subdivision`),
  KEY `fk_area_ubicacion` (`codigo_ubicacion`),
  KEY `fk_area_uh` (`id_unidad_homologada`),
  CONSTRAINT `fk_area_ubicacion` FOREIGN KEY (`codigo_ubicacion`) REFERENCES `ubicacion` (`codigo_ubicacion`),
  CONSTRAINT `fk_area_ucc` FOREIGN KEY (`id_unidad_cc`) REFERENCES `unidad_cc` (`id_unidad_cc`),
