-- =====================================================================
-- 2. Ligar Equipo con el catálogo (Equipo.UnidadID -> Equipo.AreaID)
--    Cada paso revisa primero si hace falta, así que el script se puede
--    ejecutar varias veces sin error.
-- =====================================================================

-- 2.1 Agregar la columna AreaID (opcional: el agente registra equipos sin área)
SET @sql := IF(((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo') = 1 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo' AND COLUMN_NAME = 'AreaID') = 0), 'ALTER TABLE `Equipo` ADD COLUMN `AreaID` INT UNSIGNED NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.1b Si GlassFish ya había creado AreaID como INT con signo, igualarla a area.id_area
SET @sql := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo' AND COLUMN_NAME = 'AreaID' AND COLUMN_TYPE NOT LIKE '%unsigned%') = 1, 'ALTER TABLE `Equipo` MODIFY `AreaID` INT UNSIGNED NULL', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.2 Llave foránea Equipo.AreaID -> area.id_area
SET @sql := IF(((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo' AND COLUMN_NAME = 'AreaID') = 1 AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo' AND CONSTRAINT_NAME = 'fk_equipo_area') = 0), 'ALTER TABLE `Equipo` ADD CONSTRAINT `fk_equipo_area` FOREIGN KEY (`AreaID`) REFERENCES `area` (`id_area`)', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.3 Quitar la llave foránea de UnidadID (su nombre lo generó EclipseLink)
SET @fk := (SELECT CONSTRAINT_NAME FROM information_schema.KEY_COLUMN_USAGE
             WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo'
               AND COLUMN_NAME = 'UnidadID' AND REFERENCED_TABLE_NAME IS NOT NULL LIMIT 1);
SET @sql := IF(@fk IS NULL, 'SELECT 1', CONCAT('ALTER TABLE `Equipo` DROP FOREIGN KEY `', @fk, '`'));
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.4 Quitar la columna UnidadID
SET @sql := IF(((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'Equipo' AND COLUMN_NAME = 'UnidadID') = 1), 'ALTER TABLE `Equipo` DROP COLUMN `UnidadID`', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2.5 Quitar la tabla Unidad (la reemplaza el catálogo)
DROP TABLE IF EXISTS `Unidad`;

-- =====================================================================
-- 3. Vista con la estructura completa de cada área
-- =====================================================================

-- ---------------------------------------------------------------------
-- Vista con la estructura completa de cada área (sin el responsable RCAB)
-- ---------------------------------------------------------------------
DROP VIEW IF EXISTS `v_estructura`;
CREATE VIEW `v_estructura` AS select `a`.`id_area` AS `id_area`,concat(`ucc`.`uicc`,`a`.`division`,`a`.`subdivision`) AS `union_larga`,`ucc`.`uicc` AS `union_corta`,`ui`.`clave_ui` AS `unidad_inf`,`ui`.`descripcion` AS `descripcion_unidad`,`a`.`codigo_ubicacion` AS `ubicacion`,`ub`.`descripcion` AS `descripcion_ubicacion`,`cc`.`clave_cc` AS `centro_costo`,`cc`.`descripcion` AS `descripcion_centro_costo`,`a`.`division` AS `division`,`a`.`subdivision` AS `subdivision`,`ui`.`tipo_regimen` AS `tipo_regimen`,`cl`.`tipo_unidad` AS `tipo_unidad`,`cl`.`sub_tipo_unidad` AS `sub_tipo_unidad`,`cl`.`agrupacion_tipo` AS `agrupacion_tipo`,coalesce(`rz`.`nombre`,`r`.`nombre`) AS `region`,`uh`.`num_zona` AS `zona`,`ucc`.`nombre_iman_desglosado` AS `nombre_iman_desglosado`,`uh`.`nombre` AS `nombre_homologado`,`a`.`cuenta` AS `cuenta` from (((((((((`area` `a` join `unidad_cc` `ucc` on((`ucc`.`id_unidad_cc` = `a`.`id_unidad_cc`))) join `unidad_informacion` `ui` on((`ui`.`clave_ui` = `ucc`.`clave_ui`))) join `centro_costo` `cc` on((`cc`.`clave_cc` = `ucc`.`clave_cc`))) left join `ubicacion` `ub` on((`ub`.`codigo_ubicacion` = `a`.`codigo_ubicacion`))) left join `unidad_homologada` `uh` on((`uh`.`id_unidad_homologada` = `a`.`id_unidad_homologada`))) left join `clasificacion_unidad` `cl` on((`cl`.`id_clasificacion` = `uh`.`id_clasificacion`))) left join `region` `r` on((`r`.`id_region` = `uh`.`id_region`))) left join `zona` `z` on((`z`.`num_zona` = `uh`.`num_zona`))) left join `region` `rz` on((`rz`.`id_region` = `z`.`id_region`)));

-- =====================================================================
-- 4. Verificación (debe dar: 5, 32, 24, 658, 544, 120, 956, 557, 1166)
-- =====================================================================
SELECT 'region' AS tabla, COUNT(*) AS registros FROM `region`
UNION ALL SELECT 'zona', COUNT(*) FROM `zona`
UNION ALL SELECT 'clasificacion_unidad', COUNT(*) FROM `clasificacion_unidad`
UNION ALL SELECT 'unidad_homologada', COUNT(*) FROM `unidad_homologada`
UNION ALL SELECT 'unidad_informacion', COUNT(*) FROM `unidad_informacion`
UNION ALL SELECT 'centro_costo', COUNT(*) FROM `centro_costo`
UNION ALL SELECT 'unidad_cc', COUNT(*) FROM `unidad_cc`
UNION ALL SELECT 'ubicacion', COUNT(*) FROM `ubicacion`
UNION ALL SELECT 'area', COUNT(*) FROM `area`;
